package com.luncher; import android.app.Application; import android.content.Intent; import kotlin.system.exitProcess; class LuncherApp:Application(){override fun onCreate(){super.onCreate(); Thread.setDefaultUncaughtExceptionHandler{_,e->try{val i=Intent(this,/*CrashActivity supprimée*/::class.java); i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK); i.putExtra("error",e.message+"\n"+e.stackTrace.take(20).joinToString("\n")); startActivity(i)}catch(_:Exception){}; try{Thread.sleep(2000)}catch(_:Exception){}; exitProcess(0)}}}